function someFunction() {
    alert('I am called!!');
    anotherFunction();
}

function myfunction(a, b) {
    var c = a + b;
    alert(c);
    return c;
}

function myfunction(a, b) {
    var c = a + b;
    alert(arguments.callee.caller);
    return c;
}

function myfunction(a, b) {
    var c = a + b;
    alert(anotherFunction);
    return anotherFunction(c + 'something');
}

function myfunction(a, b) {
    var c = a + b;
    if (a == 'properties') {
        alert(c);
    }
    return anotherFunction(c + 'something');
}

var debug = false;

function main() {
  debug = true; // Debug only during this execution
  myFunction(a, b);
  debug = false; // Stop debugging
}

function myfunction(a, b) {
    var c = a + b;
    if (debug) {
        alert(anotherFunction);
    }
    return anotherFunction(c + 'something');
}
